using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace YamyamCoding.Shorts.OneAction.Editor {
public static class OneActionCapture {
 const string Root="Assets/VideoScenes/shorts-mario-one-action",Asset="Assets/ThirdParty/KayKitAdventurers/";
 const int W=1080,H=1080,Fps=60,Frames=390;
 [Serializable]public class Job{public string output,mode,ffmpeg;}
 [Serializable]public class Point{public float x,y;public Point(Vector3 p){x=p.x;y=H-p.y;}}
 [Serializable]public class State{public int frame,rewards;public float time,moveInput;public string kind,controlledObject;public bool input,contact,captured,targetControlled;public Point projectile,target,caster;public Vector3 casterWorld,targetWorld;}
 [Serializable]public class Trace{public string engine;public int fps=Fps,width=W,height=H;public string query="Physics.SphereCastAll, target collider filter";public List<State> frames=new List<State>();}
 static Job job;static Camera cam;static GameObject hero,target,orb;static Material targetMat;static Vector3 targetStart,heroStart,heroScale,targetScale;
 static OneActionDemonstration demo;static Dictionary<string,AnimationClip>clips;static Texture2D pixels;static RenderTexture rt;
 static System.Diagnostics.Process ff;static Stream pipe;static int index,which;static bool prepared;static Trace trace;static State pending;
 static readonly int[] Preview={0,50,75,95,125,170,235,350};
 static Color Hex(string s){ColorUtility.TryParseHtmlString(s,out var c);return c;}
 static Material Mat(string name,string hex,Texture texture=null){var p=Root+"/Baked/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Yamyam/OneActionCharacterSurface"));AssetDatabase.CreateAsset(m,p);}m.color=Hex(hex);if(texture)m.mainTexture=texture;return m;}
 static GameObject Part(string name,PrimitiveType type,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.position=pos;g.transform.localScale=size;Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=mat;return g;}
 static GameObject Knight(string name,Vector3 at,string color){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Asset+"Knight.fbx"));g.name=name;foreach(var t in g.GetComponentsInChildren<Transform>(true))if(t.name.Contains("Sword")||t.name.Contains("Shield"))t.gameObject.SetActive(false);if(g.TryGetComponent<Animator>(out var a))a.enabled=false;var mat=Mat(name,color,AssetDatabase.LoadAssetAtPath<Texture2D>(Asset+"knight_texture.png"));foreach(var r in g.GetComponentsInChildren<Renderer>(true)){r.sharedMaterial=mat;if(r is SkinnedMeshRenderer s)s.updateWhenOffscreen=true;}clips["Idle"].SampleAnimation(g,.9f);var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);g.transform.localScale=Vector3.one*(1.8f/b.size.y);clips["Idle"].SampleAnimation(g,.9f);b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);g.transform.position=at-new Vector3(b.center.x,b.min.y,b.center.z);g.transform.rotation=Quaternion.Euler(0,which==0?0:0,0);return g;}
 public static void Run(){try{var args=Environment.GetCommandLineArgs();job=JsonUtility.FromJson<Job>(File.ReadAllText(args[Array.IndexOf(args,"-oneActionJob")+1]));Directory.CreateDirectory(job.output);Directory.CreateDirectory(Root+"/Baked");Directory.CreateDirectory(Root+"/Scenes");clips=AssetDatabase.LoadAllAssetsAtPath(Asset+"Knight.fbx").OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).ToDictionary(c=>c.name);which=0;Prepare();EditorApplication.update+=Tick;}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Prepare(){GraphicsSettings.defaultRenderPipeline=null;QualitySettings.renderPipeline=null;QualitySettings.antiAliasing=4;PlayerSettings.colorSpace=ColorSpace.Linear;var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.skybox=null;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.white;var stage=Mat("Stage","#17251F");Part("Shared demonstration stage",PrimitiveType.Cube,new Vector3(0,-.12f,0),new Vector3(5.9f,.2f,2.2f),stage);Part("Stage front edge",PrimitiveType.Cube,new Vector3(0,-.19f,.95f),new Vector3(5.9f,.13f,.12f),Mat("Edge","#315044"));hero=Knight("Caster",new Vector3(-1.8f,0,0),"#FFFFFF");heroStart=hero.transform.position;heroScale=hero.transform.localScale;hero.transform.rotation=Quaternion.Euler(0,90,0);
 if(which==0){target=Part("Reward coin",PrimitiveType.Cylinder,new Vector3(1.4f,1.05f,0),new Vector3(.72f,.075f,.72f),Mat("Reward","#FFD25A"));target.transform.rotation=Quaternion.Euler(90,0,0);var c=target.AddComponent<SphereCollider>();c.radius=.51f;c.isTrigger=true;}
 else{target=Knight("Capturable target",new Vector3(1.4f,0,0),"#CAD1D8");var c=target.AddComponent<CapsuleCollider>();c.height=1.8f/target.transform.localScale.y;c.radius=.34f/target.transform.localScale.x;c.center=new Vector3(0,.9f/target.transform.localScale.y,0);c.isTrigger=true;targetMat=target.GetComponentInChildren<Renderer>().sharedMaterial;}
 targetStart=target.transform.position;targetScale=target.transform.localScale;orb=Part("Thrown signal disk",PrimitiveType.Cylinder,new Vector3(-1.55f,1.05f,0),new Vector3(.42f,.06f,.42f),Mat("Signal","#73D7CD"));orb.transform.rotation=Quaternion.Euler(90,0,0);var ring=Part("Signal rim",PrimitiveType.Cylinder,Vector3.zero,new Vector3(.52f,.02f,.52f),Mat("Rim","#E9FFF6"));ring.transform.SetParent(orb.transform,false);ring.transform.localPosition=new Vector3(0,-.3f,0);ring.transform.localScale=new Vector3(1.24f,.4f,1.24f);demo=new GameObject("One input and target response").AddComponent<OneActionDemonstration>();demo.targetKind=(OneActionDemonstration.TargetKind)which;demo.caster=hero.transform;demo.target=target.transform;demo.projectile=orb.transform;demo.targetCollider=target.GetComponent<Collider>();demo.targetRenderers=target.GetComponentsInChildren<Renderer>();demo.idleClip=clips["Idle"];demo.throwClip=clips["Throw"];demo.walkClip=clips["Walking_A"];demo.inspectorPlayback=false;demo.ResetDemonstration();cam=new GameObject("Shared unchanged camera").AddComponent<Camera>();cam.enabled=false;cam.orthographic=true;cam.orthographicSize=2.8f;cam.aspect=1;cam.transform.position=new Vector3(0,2.7f,9);cam.transform.LookAt(new Vector3(0,1.05f,0));cam.backgroundColor=Color.black;cam.clearFlags=CameraClearFlags.SolidColor;cam.nearClipPlane=.1f;cam.farClipPlane=30;cam.allowHDR=false;rt=new RenderTexture(W,H,24,RenderTextureFormat.ARGB32){antiAliasing=4};rt.Create();pixels=new Texture2D(W,H,TextureFormat.RGBA32,false);cam.targetTexture=rt;
 demo.inspectorPlayback=true;cam.enabled=true;EditorSceneManager.SaveScene(scene,Root+"/Scenes/"+(which==0?"01-reward":"02-capture")+".unity");demo.inspectorPlayback=false;cam.enabled=false;AssetDatabase.SaveAssets();trace=new Trace{engine=Application.unityVersion};index=0;prepared=false;
 if(job.mode=="full"){var output=Path.Combine(job.output,(which==0?"reward":"capture")+".mp4");if(File.Exists(output))throw new Exception("Preserve completed capture");ff=new System.Diagnostics.Process();ff.StartInfo=new System.Diagnostics.ProcessStartInfo(job.ffmpeg,$"-hide_banner -loglevel warning -n -f rawvideo -pixel_format rgba -video_size {W}x{H} -framerate {Fps} -i pipe:0 -vf vflip -an -frames:v {Frames} -c:v libx264 -threads 4 -preset fast -crf 16 -pix_fmt yuv420p -color_primaries bt709 -color_trc bt709 -colorspace bt709 -movflags +faststart \"{output}\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardError=true};ff.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)File.AppendAllText(Path.Combine(job.output,"ffmpeg.log"),e.Data+"\n");};ff.Start();ff.BeginErrorReadLine();pipe=ff.StandardInput.BaseStream;}}
 static void ApplyInput(int f){demo.Step(1f/Fps,f==50,f>=180&&f<300?1:0);}
 static void Advance(int frame){
 if(job.mode!="full"){target.gameObject.SetActive(true);target.transform.position=targetStart;hero.transform.position=heroStart;demo.ResetDemonstration();for(int f=0;f<=frame;f++)ApplyInput(f);}else ApplyInput(frame);
 var sample=frame/(float)Fps;var hp=hero.transform.position;var tp=target.transform.position;float windup=demo.inputTime>=0?demo.Elapsed-demo.inputTime:-1;
 var heroClip=windup>=0&&windup<clips["Throw"].length?clips["Throw"]:(!demo.captured&&Mathf.Abs(demo.moveInput)>.01f?clips["Walking_A"]:clips["Idle"]);
 heroClip.SampleAnimation(hero,heroClip==clips["Throw"]?windup:sample%heroClip.length);hero.transform.position=hp;hero.transform.localScale=heroScale;hero.transform.rotation=Quaternion.Euler(0,90,0);
 if(which==1){var clip=demo.captured&&Mathf.Abs(demo.moveInput)>.01f?clips["Walking_A"]:clips["Idle"];clip.SampleAnimation(target,sample%clip.length);target.transform.position=tp;target.transform.localScale=targetScale;target.transform.rotation=Quaternion.Euler(0,demo.captured&&Mathf.Abs(demo.moveInput)>.01f?90:0,0);targetMat.color=demo.captured?Hex("#92DF9C"):Hex("#CAD1D8");}
 orb.transform.rotation=Quaternion.Euler(90,0,-sample*450);
 pending=new State{frame=frame,time=sample,kind=which==0?"reward":"capture",rewards=demo.rewards,input=demo.inputPressed,contact=demo.contact,captured=demo.captured,targetControlled=demo.targetIsControlled,moveInput=demo.moveInput,controlledObject=demo.controlledObject,casterWorld=hero.transform.position,targetWorld=target.transform.position,caster=new Point(cam.WorldToScreenPoint(hero.transform.position+Vector3.up)),target=new Point(cam.WorldToScreenPoint(target.transform.position+(which==0?Vector3.zero:Vector3.up))),projectile=new Point(cam.WorldToScreenPoint(orb.transform.position))};
 }

 static void Tick(){try{var f=job.mode=="full"?index:Preview[index];if(!prepared){Advance(f);prepared=true;EditorApplication.QueuePlayerLoopUpdate();return;}cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;pixels.ReadPixels(new Rect(0,0,W,H),0,0);pixels.Apply(false);RenderTexture.active=old;var kind=which==0?"reward":"capture";if(job.mode=="full"){var bytes=pixels.GetRawTextureData<byte>();pipe.Write(bytes.ToArray(),0,bytes.Length);}if(job.mode!="full"||Preview.Contains(f))File.WriteAllBytes(Path.Combine(job.output,$"{kind}-{f:D4}.png"),pixels.EncodeToPNG());trace.frames.Add(pending);index++;prepared=false;if(index<(job.mode=="full"?Frames:Preview.Length))return;if(ff!=null){pipe.Close();ff.WaitForExit();if(ff.ExitCode!=0)throw new Exception("Encoder failed");ff=null;}File.WriteAllText(Path.Combine(job.output,kind+"-trace.json"),JsonUtility.ToJson(trace,true));if(!trace.frames.Any(x=>x.contact))throw new Exception("Actual projectile query did not hit target");if(which++==0){Object.DestroyImmediate(rt);Object.DestroyImmediate(pixels);Prepare();return;}File.WriteAllText(Path.Combine(job.output,"success.json"),"{\"framesPerState\":"+(job.mode=="full"?Frames:Preview.Length)+",\"targetStates\":2,\"actualQuery\":true}");EditorApplication.update-=Tick;EditorApplication.Exit(0);}catch(Exception e){EditorApplication.update-=Tick;if(ff!=null&&!ff.HasExited){pipe.Close();ff.Kill();}Debug.LogException(e);EditorApplication.Exit(1);}}
}
}
